/**
 * Save generated bytes (PDFs, exports) to the user's device. Browser only; no network request is made:
 * the bytes become an in-memory Blob, a temporary object URL is clicked through a hidden anchor, and the
 * URL is revoked right after. Nothing is written to browser storage.
 */

/** Strip characters that are unsafe in file names on common operating systems. */
export function safeFilename(name: string): string {
  // eslint-disable-next-line no-control-regex
  const cleaned = name.replace(/[\\/:*?"<>|\u0000-\u001f]+/g, "-").replace(/\s+/g, " ").trim();
  return cleaned.length > 0 ? cleaned.slice(0, 120) : "download";
}

export function downloadBytes(bytes: Uint8Array, filename: string, mime = "application/pdf"): void {
  if (typeof document === "undefined" || typeof URL === "undefined" || typeof URL.createObjectURL !== "function") {
    throw new Error("downloadBytes can only run in a browser");
  }
  const blob = new Blob([new Uint8Array(bytes)], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = safeFilename(filename);
  a.rel = "noopener";
  a.style.display = "none";
  document.body.appendChild(a);
  try {
    a.click();
  } finally {
    a.remove();
    // Revoke on the next task so the browser has started the download first.
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }
}
